package com.andye.warmod.phalanx;import net.minecraft.world.phys.Vec3;public final class PhalanxBulletCollision{private PhalanxBulletCollision(){}public static boolean intersects(Vec3 a,Vec3 b,Vec3 point,double radius){Vec3 ab=b.subtract(a);double d=ab.lengthSqr();double t=d<1E-9?0:Math.max(0,Math.min(1,point.subtract(a).dot(ab)/d));return a.add(ab.scale(t)).distanceToSqr(point)<=radius*radius;}}
